CREATE   VIEW [Expenses].[vwWebEx_Claim_Detail] 
AS

SELECT 
     [Amount]
    ,[amount Without VAT]
    ,[Attendee Job Title]
    ,[Attendee Name]
    ,[Attendee Notes]
    ,[Base Amount Without VAT]
    ,[Base Ccy Amount]
    ,[Base Currency]
    ,[Category]
    ,[Category GL Code]
    ,CAST([Claim Id] AS VARCHAR(20)) AS 'Claim ID'
    ,[Event]
    ,[Event Code]
    ,[Item Number]
    ,[Item title]
    ,[Mileage]
    ,[Mileage Rate]
    ,[Mileage Rate Description]
    ,[Net Due]
    ,[No of Spent Units]
    ,[No of units]
    ,[Offset Miles]
    ,[Offset Type]
    ,[P11d Category]
    ,[Receipt Attached]
    ,[Receipt Given]
    ,[Source]
    ,[Total Miles]
    ,[travel From]
    ,[Travel Return]
    ,[travel To]
    ,[Unrecovered VAT]
    ,[VAT Amount]
    ,[VAT Name]
    ,[VAT Processed] AS [VAT Paid]
    ,[VAT Rate]
    ,[VUK Number]
  FROM [Expenses].[tblWebExpenses_Detailed]
  WHERE CAST([Date Created] AS DATE) >= '2015-08-01'
